export const getPortionTypeConfig = (typeKey) => PORTION_TYPE_CONFIGS.find((item) => item.key === typeKey) || PORTION_TYPE_CONFIGS[0];
export const getPortionInputsSummary = (config, record) => {
    const inputFields = config.fields.filter((field) => field.key !== 'description');
    if (inputFields.length === 0) {
        return '--';
    }
    return inputFields
        .map((field) => {
        const value = record === null || record === void 0 ? void 0 : record[field.key];
        return `${field.label}: ${value !== null && value !== void 0 ? value : '--'}`;
    })
        .join(', ');
};
