import React, { useEffect } from 'react';
import { setPaymentMenu, useAppDispatch } from '@igblsln/store';
import PortionsScreenMain from '../../PortionsScreen/Main/Main';
import { PORTIONS_SCREEN3_CONFIGS, PORTIONS_SCREEN3_GROUPS, PORTIONS_SCREEN3_MODELS } from '../config';
const PortionsScreen3Main = () => {
    const dispatch = useAppDispatch();
    useEffect(() => {
        dispatch(setPaymentMenu('portions3'));
        return () => {
            dispatch(setPaymentMenu(''));
        };
    }, [dispatch]);
    return (React.createElement("div", { className: "portions-screen3-shell" },
        React.createElement(PortionsScreenMain, { screenGroups: PORTIONS_SCREEN3_GROUPS, screenConfigs: PORTIONS_SCREEN3_CONFIGS, fallbackModels: PORTIONS_SCREEN3_MODELS, paymentMenuKey: "portions3", routeBase: "portions3" })));
};
export default PortionsScreen3Main;
