import React from 'react';
import { templateFn } from '@igblsln/control';
import { Link, useLocation } from 'react-router-dom';
import { MODULE_NAME } from '../constants';
const estimationTemplateFn = (page, isCommingSoon) => {
    return templateFn(`/${MODULE_NAME}/${page}` + (isCommingSoon ? '/comming-soon' : ''));
};
const sectionObjectBlockTemplate = (item, options) => {
    const SectionObjectBlockLink = () => {
        const location = useLocation();
        const active = location.pathname === `/${MODULE_NAME}/section-object` || location.pathname === `/${MODULE_NAME}/section-object/`;
        return React.createElement(Link, { to: `/${MODULE_NAME}/section-object`, onClick: item.command, className: `${options.className || ''}${active ? ' p-menuitem-active' : ''}`, style: { textDecoration: 'none' } },
            React.createElement("span", { className: options.iconClassName }),
            React.createElement("span", { className: options.labelClassName }, item.label));
    };
    return React.createElement(SectionObjectBlockLink, null);
};
