import { useSyncExternalStore } from 'react';
const INITIAL_ITEM_SPECS = [
    {
        key: 1,
        spec_name: 'RCC Work Spec',
        labour_contract_rate: '200',
        labour_uom: null,
        material_contract_rate: '500',
        material_uom: null,
        specifications: [{ id: 'spec_1', spec_param_name: 'Grade', param_value: 'M20' }],
        material_items: [{ id: 'mat_1', item_name: '', quantity_type: 'Fixed', quantity: '', uom: '' }],
        labour_items: [{ id: 'lab_1', labour_type: '', rate: '', no_of_labours: '' }],
        brand_items: [],
    },
    {
        key: 2,
        spec_name: 'Plastering Work Spec',
        labour_contract_rate: '120',
        labour_uom: null,
        material_contract_rate: '340',
        material_uom: null,
        specifications: [],
        material_items: [],
        labour_items: [],
        brand_items: [],
    },
];
let items = [...INITIAL_ITEM_SPECS];
let nextKey = 1000;
const listeners = new Set();
const emit = () => listeners.forEach((cb) => cb());
export const itemSpecStore = {
    getItems: () => items,
    getItem: (key) => items.find((i) => i.key === key),
    add: (item) => {
        const key = ++nextKey;
        items = [...items, Object.assign(Object.assign({}, item), { key })];
        emit();
        return key;
    },
    update: (key, item) => {
        items = items.map((i) => (i.key === key ? Object.assign(Object.assign({}, i), item) : i));
        emit();
    },
    remove: (key) => {
        items = items.filter((i) => i.key !== key);
        emit();
    },
    subscribe: (cb) => {
        listeners.add(cb);
        return () => {
            listeners.delete(cb);
        };
    },
};
export const useItemSpecs = () => useSyncExternalStore(itemSpecStore.subscribe, itemSpecStore.getItems, itemSpecStore.getItems);
