import { api, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/worksheetdisplay/';
export const workSheetDisplayApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listWorkSheetDisplay: build.query({
            query: () => ({
                url: urlUtils(API_PATH, `?without_pagination=1`),
            }),
        }),
    }),
});
export const { useListWorkSheetDisplayQuery, } = workSheetDisplayApi;
